import java.util.*;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;

public class Main {
    public static void main(String[] args) throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        JsonNode akar = mapper.readTree(new Scanner(System.in).nextLine());
        int jumlah = 0;
        int total = 0;
        for (JsonNode p : akar.get("pesanan")) {
            if (p.get("status").asText().equals("LUNAS")) {
                jumlah++;
                total += p.get("total").asInt();
            }
        }
        System.out.println("Lunas: " + jumlah + " pesanan, total Rp" + total);
    }
}
